class Solution {
    int gcd(int a,int b){while(b){int t=a%b;a=b;b=t;}return a;}
public:
    long long interchangeableRectangles(vector<vector<int>>& rectangles){
        map<pair<int,int>,long long>freq;long long ans=0;
        for(auto &r:rectangles){int g=gcd(r[0],r[1]);pair<int,int> key={r[0]/g,r[1]/g};
            ans+=freq[key]++;}return ans;
    }
};
